// GENERATED by scripts/build_workflows.mjs from n8n/src - do not edit in the n8n UI.

// ---- core/render.js
// Contract messages -> WhatsApp Cloud API payloads, enforcing Meta's field
// limits. Meta rejects the WHOLE message if any field is too long, so we
// truncate here rather than lose the reply.
const LIMITS = {
  text: 4096,
  body: 1024,         // interactive body
  buttonTitle: 20,
  maxButtons: 3,
  listButton: 20,
  sectionTitle: 24,
  rowTitle: 24,
  rowDescription: 72,
  maxRows: 10,
  id: 256,
};

function cut(s, n) {
  const str = String(s ?? '');
  const chars = Array.from(str); // count code points, not UTF-16 units (Hindi/emoji)
  return chars.length <= n ? str : chars.slice(0, n - 1).join('') + '…';
}

// Split long text at paragraph/line boundaries so each part fits.
function splitText(text, max = LIMITS.text) {
  const parts = [];
  let rest = String(text ?? '');
  while (Array.from(rest).length > max) {
    const chars = Array.from(rest);
    const window = chars.slice(0, max).join('');
    let at = window.lastIndexOf('\n\n');
    if (at < max / 2) at = window.lastIndexOf('\n');
    if (at < max / 2) at = window.lastIndexOf(' ');
    if (at <= 0) at = window.length;
    parts.push(window.slice(0, at).trimEnd());
    rest = rest.slice(at).trimStart();
  }
  if (rest.length || parts.length === 0) parts.push(rest);
  return parts;
}

function renderMessage(msg, to) {
  const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };
  switch (msg.type) {
    case 'text':
      return splitText(msg.body).map((body) => ({ ...base, type: 'text', text: { body, preview_url: true } }));
    case 'buttons':
      return [{
        ...base,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: cut(msg.body, LIMITS.body) },
          action: {
            buttons: (msg.buttons || []).slice(0, LIMITS.maxButtons).map((b) => ({
              type: 'reply',
              reply: { id: cut(b.id, LIMITS.id), title: cut(b.title, LIMITS.buttonTitle) },
            })),
          },
        },
      }];
    case 'list': {
      let remaining = LIMITS.maxRows;
      const sections = [];
      for (const s of msg.sections || []) {
        if (remaining <= 0) break;
        const rows = (s.rows || []).slice(0, remaining).map((r) => {
          const row = { id: cut(r.id, LIMITS.id), title: cut(r.title, LIMITS.rowTitle) };
          if (r.description) row.description = cut(r.description, LIMITS.rowDescription);
          return row;
        });
        remaining -= rows.length;
        if (rows.length) sections.push({ title: cut(s.title || '', LIMITS.sectionTitle), rows });
      }
      return [{
        ...base,
        type: 'interactive',
        interactive: {
          type: 'list',
          body: { text: cut(msg.body, LIMITS.body) },
          action: { button: cut(msg.button || 'Menu', LIMITS.listButton), sections },
        },
      }];
    }
    case 'location':
      return [{
        ...base,
        type: 'location',
        location: { latitude: msg.lat, longitude: msg.lon, name: msg.name || '', address: msg.address || '' },
      }];
    case 'location_request':
      return [{
        ...base,
        type: 'interactive',
        interactive: { type: 'location_request_message', body: { text: cut(msg.body, LIMITS.body) }, action: { name: 'send_location' } },
      }];
    case 'template':
      return [{ ...base, type: 'template', template: msg.template }];
    default:
      throw new Error(`unknown message type: ${msg.type}`);
  }
}

// All user-visible strings in a payload (for the phone guard and logging).
function visibleText(payload) {
  const out = [];
  if (payload.text) out.push(payload.text.body);
  const i = payload.interactive;
  if (i) {
    out.push(i.body && i.body.text);
    for (const b of (i.action && i.action.buttons) || []) out.push(b.reply.title);
    for (const s of (i.action && i.action.sections) || []) {
      out.push(s.title);
      for (const r of s.rows) out.push(r.title, r.description);
    }
  }
  if (payload.location) out.push(payload.location.name, payload.location.address);
  return out.filter(Boolean).join('\n');
}

// ---- core/phone_guard.js
// Find phone-number-like tokens in outgoing text. Every one of them must exist
// in core.number_registry (checked in SQL by core.disallowed_numbers), so the
// bot can never send a number that isn't in the verified data.
const CANDIDATE = /\+?\d[\d \t-]{4,}\d/g; // spaces/hyphens inside one line only - never across a line break
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const DECIMAL = /\d+\.\d+/g; // coordinates/distances in map links, e.g. 25.678912,85.123456

function extractPhones(text) {
  const found = new Set();
  const scanned = String(text || '').replace(DECIMAL, ' ');
  for (const m of scanned.matchAll(CANDIDATE)) {
    const token = m[0].trim();
    if (ISO_DATE.test(token)) continue;
    const digits = token.replace(/\D/g, '');
    if (digits.length < 6 || digits.length > 13) continue;
    found.add(digits);
  }
  return Array.from(found);
}

// ---- core/deliver.js
// Render -> phone guard -> WhatsApp Cloud API, strictly one message after
// another (awaiting each response) so a citizen's messages arrive in order.
// Returns one log entry per payload for core.rpc_finish_turn().
// Depends on: renderMessage/visibleText (render.js), extractPhones (phone_guard.js).
// `allowed` = normalised numbers from core.number_registry; `http` = this.helpers.httpRequest.
function normDigits(p) {
  const d = String(p || '').replace(/\D/g, '');
  return /^91[6-9]\d{9}$/.test(d) ? d.slice(2) : d;
}

async function deliverMessages(send, allowed, cfg, http) {
  const ok = new Set((allowed || []).map(normDigits));
  const url = `${cfg.base || 'https://graph.facebook.com'}/${cfg.version || 'v23.0'}/${cfg.phoneId}/messages`;
  const logs = [];
  for (const m of (send && send.messages) || []) {
    for (let payload of renderMessage(m, send.to)) {
      let text = visibleText(payload);
      let blocked = null;
      const bad = extractPhones(text).filter((p) => !ok.has(normDigits(p)));
      if (bad.length) {
        // A number that is not in the verified data must never reach a citizen.
        blocked = bad;
        text = send.lang === 'en' ? 'Sorry, this information is not available right now.' : 'माफ़ कीजिए, यह जानकारी अभी उपलब्ध नहीं है।';
        payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: send.to, type: 'text', text: { body: text } };
      }
      let result = null;
      for (let attempt = 1; attempt <= 2 && !result; attempt++) {
        try {
          const res = await http({ method: 'POST', url, json: true, body: payload, timeout: 10000,
            headers: { Authorization: `Bearer ${cfg.token}` }, returnFullResponse: true, ignoreHttpStatusErrors: true });
          const retryable = res.statusCode === 429 || res.statusCode >= 500;
          if (res.statusCode < 300) result = { out_id: ((res.body.messages || [])[0] || {}).id || null, error: null };
          else if (!retryable || attempt === 2) result = { out_id: null, error: `HTTP ${res.statusCode}: ${JSON.stringify(res.body).slice(0, 400)}` };
        } catch (e) {
          if (attempt === 2) result = { out_id: null, error: String(e.message || e).slice(0, 400) };
        }
        if (!result) await new Promise((r) => setTimeout(r, 1000));
      }
      logs.push({ wa_hash: send.wa_hash, service_key: send.service_key, kind: m.type, text,
        out_id: result.out_id, error: result.error || (blocked ? `phone_guard:${blocked.join(',')}` : null) });
    }
  }
  return logs;
}

// ---- main

const s = $('When Called').item.json.send;
const logs = await deliverMessages(s, $json.allowed, {
  base: $env.WA_API_BASE, version: $env.GRAPH_API_VERSION, phoneId: $env.WHATSAPP_PHONE_NUMBER_ID, token: $env.WHATSAPP_ACCESS_TOKEN,
}, this.helpers.httpRequest.bind(this.helpers));
return { json: { finish: { end: null, outs: logs } } };
